"""Matched single-bend terrain appraisal: geometry, skyline, photos and timing."""
import collections,csv,json,math,re
from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw
from sidewinder_canyon_rebuild import ROOT,BASE,OUT,visible_chunks,sections
from photo_sidewinder_structures import load_bank,render
from report_world_lod import subset
CAND=OUT/'candidate'

def selected(bank,data,levels):
    codes=np.array(data['lod_chunks'])[bank[2]];groups=np.maximum(0,(codes-1)//2);keep=(codes==0)|(levels[groups]==(codes-1)%2)
    return subset(bank,keep)

def photos():
    before=load_bank(BASE/'candidate-maps/sidewinder.map64');after=load_bank(CAND/'candidate-maps/sidewinder.map64');control=load_bank(OUT/'control/candidate-maps/sidewinder.map64');old=json.loads((BASE/'visibility.json').read_text());new=json.loads((CAND/'visibility.json').read_text());ctrl=json.loads((OUT/'control/visibility.json').read_text());poses=json.loads((CAND/'photos/poses.json').read_text());cams={int(r['tick']):r for r in csv.DictReader((CAND/'photos/cameras.csv').open()) if r['candidate']=='1'};directory=OUT/'photos';directory.mkdir(exist_ok=True);results=[];contacts=[]
    for row in csv.reader((CAND/'photos/lod-trace.csv').open()):
        photo=int(row[0]);matrix=np.array(list(map(float,row[2:18]))).reshape(4,4);levels=np.array(list(map(int,row[18:])));mask=int(cams[photo]['pvs_mask']);a_bank=selected(before,old,levels);b_bank=selected(after,new,levels);c_bank=selected(control,ctrl,levels)
        a=render(a_bank,matrix,old['chunk_masks'],mask);b=render(b_bank,matrix,new['chunk_masks'],mask);c=render(c_bank,matrix,ctrl['chunk_masks'],mask);un=render(b_bank,matrix)
        diff=np.abs(a.astype(np.int16)-b.astype(np.int16));pdiff=np.abs(un.astype(np.int16)-b.astype(np.int16));geometry=np.abs(c.astype(np.int16)-b.astype(np.int16))
        masks=[]
        for bank,meta in ((a_bank,old),(b_bank,new)):
            terrain=subset(bank,np.isin(bank[1],[7,8,9]));_,m=render(terrain,matrix,meta['chunk_masks'],mask,return_mask=True);masks.append(m)
        aa,bb=masks;both=aa.any(0)&bb.any(0);y0=np.argmax(aa,axis=0);y1=np.argmax(bb,axis=0);sky=np.abs(y0-y1)[both];overlay=np.full_like(a,(18,24,34));overlay[aa&bb]=(175,190,203);overlay[aa&~bb]=(40,211,246);overlay[bb&~aa]=(255,136,58)
        for label,im in [('before',a),('after',b),('difference',np.clip(diff*6,0,255).astype(np.uint8)),('skyline',overlay),('pvs-control',un),('batching-control',c),('geometry-difference',np.clip(geometry*6,0,255).astype(np.uint8))]:Image.fromarray(im).save(directory/f'{photo:02}-{label}.png')
        record=dict(photo=photo,label=poses[photo]['label'],pose=poses[photo],matrix_columns=matrix.tolist(),selected_levels=levels.tolist(),changed_pixels=int(np.count_nonzero(diff.max(2))),mean_rgb_error=float(diff.mean()),pvs_control_changed_pixels=int(np.count_nonzero(pdiff.max(2))),geometry_vs_batching_control_changed_pixels=int(np.count_nonzero(geometry.max(2))),terrain_coverage_changed_pixels=int(np.count_nonzero(aa^bb)),skyline_changed_columns=int(np.count_nonzero(sky)),max_skyline_y_shift_pixels=int(sky.max()) if len(sky) else 0,coverage_column_presence_changes=int(np.count_nonzero(aa.any(0)^bb.any(0))))
        results.append(record);im=Image.new('RGB',(1280,265),(18,24,34));im.paste(Image.fromarray(a),(0,25));im.paste(Image.fromarray(b),(640,25));d=ImageDraw.Draw(im);d.text((8,5),f'{photo:02} {record["label"]} / world LOD baseline',fill='white');d.text((648,5),'east bend rebuild',fill='white');contacts.append(im);print(photo,record['changed_pixels'],'pixels, skyline',record['max_skyline_y_shift_pixels'],'PVS',record['pvs_control_changed_pixels'],flush=True)
    im=Image.new('RGB',(1280,len(contacts)*265),(18,24,34))
    for i,row in enumerate(contacts):im.paste(row,(0,i*265))
    im.save(OUT/'photo-contact.png');(OUT/'photos.json').write_text(json.dumps(results,indent=2)+'\n')

def costs():
    results={}
    for ds in ('replay','photos'):
        old=visible_chunks((BASE/'candidate-maps/sidewinder.map64').read_bytes(),json.loads((BASE/'visibility.json').read_text()),ds)
        new=visible_chunks((CAND/'candidate-maps/sidewinder.map64').read_bytes(),json.loads((CAND/'visibility.json').read_text()),ds,CAND/ds)
        control=visible_chunks((OUT/'control/candidate-maps/sidewinder.map64').read_bytes(),json.loads((OUT/'control/visibility.json').read_text()),ds,verify=False)
        results[ds]=dict(samples=len(old),before_mean=float(np.mean([r['vertices'] for r in old])),after_mean=float(np.mean([r['vertices'] for r in new])),batching_control_mean=float(np.mean([r['vertices'] for r in control])),per_camera=[dict(tick=a['tick'],camera=a['camera'],before=a['vertices'],control=c['vertices'],after=b['vertices']) for a,b,c in zip(old,new,control)])
    (OUT/'costs.json').write_text(json.dumps(results,indent=2)+'\n')


def report():
    costs=json.loads((OUT/'costs.json').read_text());metrics=json.loads((OUT/'candidate/measurements.json').read_text());photos=json.loads((OUT/'photos.json').read_text());author=json.loads((OUT/'authored.json').read_text());packing=json.loads((CAND/'packing-report.json').read_text());timing=json.loads((OUT/'timing.json').read_text()) if (OUT/'timing.json').exists() else {};dense=json.loads((OUT/'dense-surface-check.json').read_text())
    rows=''.join(f'<tr><td>{name}</td><td>{r["samples"]}</td><td>{r["before_mean"]:,.1f}</td><td>{r["batching_control_mean"]:,.1f}</td><td>{r["after_mean"]:,.1f}</td><td>{100*(1-r["after_mean"]/r["before_mean"]):.2f}%</td><td>{metrics[name]["after_worst"]:,}</td></tr>' for name,r in costs.items())
    native=''.join(f'<tr><td>{name}</td><td>{r["baseline_fps"]:.3f}</td><td>{r["candidate_fps"]:.3f}</td><td>{r["gain_percent"]:+.2f}%</td><td>{r["baseline_p95_ms"]:.3f} → {r["candidate_p95_ms"]:.3f}</td></tr>' for name,r in timing.items())
    data=[dict(label=f'{r["photo"]:02} {r["label"]}',prefix=f'photos/{r["photo"]:02}',meta=r) for r in photos]
    if (OUT/'native-photos.json').exists():data.append(dict(label='Native Ares / photo 14 EAST BEND',prefix='native/images/14',meta=json.loads((OUT/'native-photos.json').read_text()),native=True))
    page='''<!doctype html><meta charset="utf-8"><title>Sidewinder — east bend terrain appraisal</title><style>body{background:#121822;color:#e9eff5;font:16px system-ui;max-width:1300px;margin:32px auto;padding:0 22px;line-height:1.55}h1,h2{line-height:1.2}a{color:#9ddcff}p{max-width:1080px}table{border-collapse:collapse;font-variant-numeric:tabular-nums}td,th{text-align:right;padding:9px 12px;border-bottom:1px solid #3b4a5c}td:first-child,th:first-child{text-align:left}.pair{display:grid;grid-template-columns:1fr 1fr;gap:14px}.pair img{width:100%;aspect-ratio:4/3;object-fit:fill;image-rendering:pixelated}.viewer{padding:16px;border:1px solid #3d4d63;margin:24px 0}select,button{background:#293747;color:white;border:1px solid #5c7089;padding:9px;margin:5px;max-width:95%}#filter{max-width:950px;width:100%;aspect-ratio:4/3;image-rendering:pixelated}pre{white-space:pre-wrap;max-height:300px;overflow:auto;font-size:12px}.note{color:#b7c8da}summary{cursor:pointer}.overview{max-width:650px;width:100%}</style>
    <h1>East canyon bend — terrain rebuild appraisal</h1><p>This private experiment targets the upper eastern canyon arc: source triangle centroids at x ≥ 0 and z &lt; −16 world units. It starts from the latest world-LOD candidate, retaining the same conservative visibility, tree/base LOD and camera fixtures elsewhere. The patch joins the same unmodified terrain and structures.</p>
    <p><b>The result is a small improvement, chiefly from vertex packing rather than a substantial terrain reconstruction.</b> The selected patch goes from 747 to 719 triangles (3.7%). Attempts to collapse it much further displaced the snow surface or changed its coverage and were rejected. This pass therefore does not establish the large terrain savings we hoped for, and has not been adopted or rolled out.</p>
    <h2>What was rebuilt and protected</h2><ul><li>The cliff and snow meshes were reconstructed in Blender across old tile/PVS partitions, with packing-only UV wrap offsets aligned before joining surfaces. The final constrained trial retains separate material interfaces; a more aggressive joined-material trial failed the surface checks.</li><li>All 76 walkable rock triangles retain their exact geometry. Joins to the unmodified terrain and cliff/snow attachment edges stay exact. Fifty sampled skyline support vertices remain fixed. Skyline images are checked separately; these anchors are not a universal silhouette guarantee.</li><li>Snow is modestly retriangulated. The final dense check samples '''+f'{dense["samples"]:,} points at up to {dense["spacing_world_units"]} world-unit spacing and finds a maximum symmetric surface distance of {dense["max_symmetric_snow_surface_distance"]:.5f} world units. This is sampled, not a continuous bound.'+''' The saved route stations on this patch have exactly matching rendered surface heights.</li><li>Collision, movement data, spawns, structures, scenery, source textures and gameplay bank sections remain byte-identical to the baseline. All 24 complete photo-route player states match byte for byte, including coordinates, angles, crouch, velocity and animation. All 68 replay camera eyes and view states match.</li><li>The patch uses a fixed rebuilt representation, replacing its former local terrain LOD chunks; other LOD groups are unchanged. Twelve-unit spatial batching was selected from five measured sizes. Source lightmap colors may merge within eight byte values per channel; source textures and texture wrap remain unchanged. The control below uses the same new packing and LOD policy with the original patch triangles, isolating the incremental geometry contribution.</li></ul>
    <h2>Matched static-world vertex loads</h2><table><tr><th>Workload</th><th>Cameras</th><th>World-LOD baseline</th><th>Original geometry / new packing policy</th><th>Rebuilt patch</th><th>Net reduction</th><th>Worst new camera</th></tr>'''+rows+'''</table><p>These are submitted paired vertex loads, including padding and batch duplication, after per-camera LOD, PVS and SDK frustum checks. Dynamic objects are additional. Only a small fraction of the saving separates the original-geometry control from the rebuilt candidate. The 1,500-load target remains unmet in most views: '''+f'{metrics["replay"]["below_1500"]}/68 replay views and {metrics["photos"]["below_1500"]}/24 photo views are below target.'+'''</p>
    <h2>Native Ares performance</h2><p>Fresh paired runs use the same NTSC benchmark: 8 MiB Expansion Pak, release LTO, three surfaces, 32 KiB queues, 1-second warmup and 75 seconds of fresh-pose sampling. Single player follows the walking-photo benchmark; four players use the production replay. No physical-console claim.</p><table><tr><th>Workload</th><th>Baseline FPS</th><th>Rebuild FPS</th><th>Change</th><th>P95 frame ms</th></tr>'''+native+'''</table>
    <h2>Same 24 cameras, before / after / differences</h2><p>These full-route images use the actual packed banks, saved SDK cameras, selected LOD levels and PVS masks. They are offline float renders with nearest texture sampling, not RDP emulation; native photo 14 is separately captured below. Diff RGB is amplified six times. The terrain coverage view uses gray for shared coverage, cyan for baseline-only pixels and orange for candidate-only pixels.</p>
    <div class="viewer"><button id="previous">Previous</button><select id="choice"></select><button id="next">Next</button><p id="description"></p><div class="pair"><div><b>World-LOD baseline</b><img id="before"></div><div><b>East bend candidate</b><img id="after"></div></div><p><select id="mode"><option value="difference">RGB difference ×6</option><option value="blend">Before / after blend</option><option value="skyline">Terrain coverage and skyline</option><option value="batching-control">Original geometry / new packing control</option><option value="geometry-difference">Rebuild versus packing control ×6</option><option value="pvs-control">PVS-disabled candidate</option></select><input id="mix" type="range" min="0" max="100" value="50"></p><canvas id="filter"></canvas><details><summary>Exact pose, matrix, LOD levels and image checks</summary><pre id="metadata"></pre></details></div>
    <h2>Native photo 14</h2><div class="pair"><div><b>Baseline</b><img src="native-photo14-baseline.png"></div><div><b>Candidate</b><img src="native-photo14-candidate.png"></div></div><p>The same frozen walking-route pose includes coordinates, yaw, pitch, crouch, grounded state, weapon and zoom in its native overlay. The viewer also offers the native difference filter. The helper's native coordinate logging was corrected to use supported decimal float formatting.</p>
    <h2>Evidence and limitations</h2><p>All 24 candidate PVS-on/off photo controls have zero changed pixels. The saved terrain skyline shifts by at most '''+str(max(r['max_skyline_y_shift_pixels'] for r in photos))+''' vertical pixel(s) in this route. This is a finite set of camera checks, not a proof for all gameplay views. The larger coupled-wall/floor collapse was rejected for surface errors; no ice-covered terrain faces could be certified removable by the initial coverage search. The current bend mesh is already coarse and its attachment contours constrain further reduction strongly. More ambitious terrain redesign would need explicit new contours and a playable-surface error budget, with wider traversal checks.</p>
    <p><a href="photos.json">Exact photos and pixel checks</a> · <a href="costs.json">Per-camera loads and control</a> · <a href="candidate/replay/cameras.csv">Replay CSV</a> · <a href="candidate/photos/cameras.csv">Photo CSV</a> · <a href="timing.json">Native timing</a> · <a href="authored.json">Blender trials</a> · <a href="dense-surface-check.json">Dense snow-surface check</a> · <a href="route-surface-heights.json">Route surface heights</a> · <a href="batching-trials.json">Batching trials</a> · <a href="native-census.png">Native census</a> · <a href="rdp-validation.png">RDP validation</a> · <a href="validation.json">Validation manifest</a> · <a href="canyon-appraisal.blend">Blender file</a></p><details><summary>Terrain overview and route stations</summary><img class="overview" src="terrain-overview.png"></details>
    <script>const records='''+json.dumps(data)+''';const $=id=>document.getElementById(id);let index=14;$('choice').innerHTML=records.map((r,i)=>`<option value="${i}">${r.label}</option>`).join('');function update(){const r=records[index];$('choice').value=index;$('before').src=r.prefix+'-before.png';$('after').src=r.prefix+'-after.png';$('metadata').textContent=JSON.stringify(r.meta,null,2);$('description').textContent=r.native?'Native Ares renderer; same frozen pose and overlay.':`${r.meta.changed_pixels} changed RGB pixels; maximum terrain skyline shift ${r.meta.max_skyline_y_shift_pixels}px; PVS-control changes ${r.meta.pvs_control_changed_pixels}.`;draw()}function draw(){let r=records[index],canvas=$('filter'),ctx=canvas.getContext('2d');if($('mode').value==='blend'){let a=new Image(),b=new Image();a.onload=()=>{b.onload=()=>{canvas.width=a.width;canvas.height=a.height;ctx.globalAlpha=1;ctx.drawImage(a,0,0);ctx.globalAlpha=$('mix').value/100;ctx.drawImage(b,0,0);ctx.globalAlpha=1};b.src=r.prefix+'-after.png'};a.src=r.prefix+'-before.png';return}let mode=$('mode').value;if(r.native)mode='difference';let im=new Image();im.onload=()=>{canvas.width=im.width;canvas.height=im.height;ctx.drawImage(im,0,0)};im.src=r.prefix+'-'+mode+'.png'}$('choice').onchange=()=>{index=+$('choice').value;update()};$('previous').onclick=()=>{index=(index+records.length-1)%records.length;update()};$('next').onclick=()=>{index=(index+1)%records.length;update()};$('mode').onchange=draw;$('mix').oninput=draw;update();</script>'''
    (OUT/'comparison.html').write_text(page)

